function randomInt(n){if(root.crypto?.getRandomValues){const a=new Uint32Array(1);root.crypto.getRandomValues(a);return a[0]%n}serial=(serial*1664525+1013904223+(Date.now()%65521))>>>0;return serial%n}
function shuffled(a){a=a.slice();for(let i=a.length-1;i>0;i--){const j=randomInt(i+1);[a[i],a[j]]=[a[j],a[i]]}return a}
// Clean binary floating-point noise in presentation only; never write the earned-XP ledger.
 function number(n){const shown=typeof n==='number'&&Number.isFinite(n)&&!Number.isInteger(n)?Number(n.toPrecision(15)):n;return api.format?api.format(shown):String(shown)}
// Actual Level18 unlocks optional display precision; no raw award/bank/receipt is rounded here.
function xpDecimals(){const n=progress().level>=18?api.getSettings?.()?.xpDecimals:undefined;return Number.isInteger(n)&&n>=0&&n<=10?n:5}
