 function celebrate(result){if(!api||!result||result.toLevel<=result.fromLevel)return;refresh();clearTimeout(celebrationTimer);$('#level-celebration')?.remove();const el=document.createElement('aside');el.id='level-celebration';el.className='level-celebration';el.setAttribute('role','status');el.setAttribute('aria-live','polite');const earned=[];for(let i=result.fromLevel+1;i<=result.toLevel;i++)if(!rewards(i).startsWith('Keep '))earned.push(rewards(i));el.innerHTML='<div class="level-star">✦</div><div class="eyebrow">LEVEL UP!</div><strong>Level '+number(result.toLevel)+'</strong><p>'+escape(earned.join(' · ')||rewards(result.toLevel))+'</p>';for(let i=0;i<20;i++){const particle=document.createElement('i');particle.style.setProperty('--particle-x',Math.cos(i*Math.PI/10)*(80+i%4*23)+'px');particle.style.setProperty('--particle-y',Math.sin(i*Math.PI/10)*90+'px');particle.style.setProperty('--particle-hue',String(i*18));particle.style.animationDelay=i%4*.08+'s';el.append(particle)}document.body.append(el);root.BOAudio?.sfx('win',{intensity:.65});celebrationTimer=setTimeout(()=>el.remove(),5000)}
