function workingDefaultsNote(){const c=xpConfig(),cost25=P().cost(25,c),cost35=P().cost(35,c),f=api.faucetConfig?.().claimRequirements||{},entries=Object.keys(c.costOverrides||{}).map(level=>Number(level)+1).sort((a,b)=>a-b);return '<p class="inline-note"><b>Configured XP requirements:</b> player level 25 → 26 currently needs '+(cost25===null?'TBD':exactXp(cost25))+' XP; level 35 → 36 currently needs '+(cost35===null?'TBD':exactXp(cost35))+' XP, including permanent reductions and any active Discount Potion. '+(entries.length?'Final normal entry-cost overrides apply to Levels '+entries.map(number).join(', ')+', after permanent reductions. Discount Potion still takes another 10% off those normal requirements (rounded up). ':'')+'For other configured transitions from Level 35 onward, growth is ×'+(c.exponentialFactor||'?')+' per level before integer rounding and permanent reductions; overridden entries do not use this formula. Faucet levels 3 / 14 use '+(f[3]?number(f[3]):'TBD')+' / '+(f[14]?number(f[14]):'TBD')+' claims. Interest rate and its 5 XP/sec cap never increase these XP requirements. These balancing defaults can be adjusted in a later update.</p>'}
function details(page){detailCostSignature=xpCostSignature();if(P().buffs(progress().level).enhancedLevelsUI){enhancedDetails(page);return}const p=progress(),last=Math.floor((playerMax()-1)/11),unlocked=Math.min(last,Math.floor(p.level/11));roadmapPage=Number.isInteger(page)&&page>=0&&page<=unlocked?page:unlocked;const start=roadmapPage===0?1:roadmapPage*11,end=Math.min(playerMax(),(roadmapPage+1)*11),rows=[];for(let i=start;i<=end;i++){const cost=i===p.level?P().progress(p,xpConfig()).required:P().cost(i,xpConfig());rows.push('<article class="level-roadmap-row '+(i<=p.level?'earned':'')+'"><b>Level '+number(i)+'</b><span>'+escape(rewards(i))+'</span><small>'+ (i===playerMax()?'MAX PLAYER LEVEL':cost===null?'XP to next not supplied yet':exactXp(cost)+' XP to next')+'</small></article>')}const tabs=[];for(let i=0;i<=Math.min(last,unlocked+1);i++){const from=i===0?1:i*11,to=Math.min(playerMax(),(i+1)*11);tabs.push('<button class="btn ghost small '+(i===roadmapPage?'roadmap-active':'')+'" data-level-action="roadmap-page" data-page="'+i+'" '+(i>unlocked?'disabled':'')+'>'+from+'–'+to+(i>unlocked?' · Level '+from:'')+'</button>')}api.openModal('Player levels · '+start+'–'+end,'<p>Your level persists across runs. Rewards apply immediately; XP at a locked cap is banked, not lost.</p>'+workingDefaultsNote()+'<p>Base action XP: 1 per actual $1 spent, +3 per shop Joker purchase, +3 per successful Tarot use, +5 per Small/Big Blind skip, and 1 per card played. Small/Big/Boss wins: 3/5/10 × Ante. Positive hand-level gains: 3 XP each. Level15, Exp Potion, active physical Exp Jokers and manual22 multipliers apply to action rewards. Interest and Knowledge use their own fixed/capped rules.</p><p>'+escape(capRulesText(p))+'</p><nav class="roadmap-pages" aria-label="Buff pages">'+tabs.join('')+'</nav><div class="level-roadmap">'+rows.join('')+'</div><div class="sheet-actions">'+graphButton()+'</div>')}
