function faucetPercent(f){return f.maxLevel?100:f.requiredClaims===null?0:Math.min(100,Math.max(0,f.totalClaims/f.requiredClaims*100))}
function faucetFraction(f){return f.maxLevel?'MAX':number(f.totalClaims)+' / '+(f.requiredClaims===null?'?':number(f.requiredClaims))+' claims'}
function faucetRemaining(f){const n=f.remainingClaims;return n===null?'':n+' '+(n===1?'claim':'claims')+' to the next level!'}
function faucetPercentText(f){return !f.maxLevel&&f.requiredClaims===null?'TBD':(f.level>=6?faucetPercent(f).toFixed(2):String(Math.round(faucetPercent(f)*100)/100))+'%'}
function faucetMotionOff(){return api.motionEnabled?api.motionEnabled()===false:document.body.matches('.reduced-motion,.motion-off')}
function faucetStyleClasses(f){return [2,3,4,5,6,7].filter(level=>f.level>=level).map(level=>'faucet-style-'+level).join(' ')}
function syncFaucetStyle(box,f){box.dataset.faucetLevel=String(f.level);for(let level=2;level<=7;level++)box.classList.toggle('faucet-style-'+level,f.level>=level);box.classList.toggle('faucet-motion-off',faucetMotionOff())}
