document.addEventListener('click',event=>{const el=event.target.closest('[data-level-action]');if(!el||el.disabled||!api)return;const action=el.dataset.levelAction;if(action==='details'||action==='next-reward'||action==='interest-details')details();else if(action==='roadmap-page')details(Number(el.dataset.page));else if(action==='faucet-graph')showGraph();else if(action==='graph-metric')showGraph(el.dataset.metric);else if(action==='graph-point')showGraphPoint(Number(el.dataset.level));else if(action==='faucet-levels')showFaucetLevels();else if(action==='faucet-preview'){showFaucetLevels(Number(el.dataset.level));const focus=document.getElementById(el.id)||$('#faucet-preview-select');(focus&&!focus.disabled?focus:$('#faucet-preview-select'))?.focus({preventScroll:true})}else if(action==='faucet')showFaucet();else if(action==='emerald-claim')assistFaucet();else if(action==='begin-claim')beginClaim();else if(action==='check-captcha')checkCaptcha();else if(action==='math-captcha'&&attempt){attempt.kind='math';attempt.a=2+randomInt(18);attempt.b=2+randomInt(18);renderCaptcha()}else if(action==='quiz-answer')answerQuiz(Number(el.dataset.choice));else if(action==='close-faucet-thanks')api.closeModal();else if(action==='coin-unlocks')coinUnlocks();else if(action==='unlock-joker')unlockJoker(el.dataset.id,el.closest('#dialog-body')?'modal':'collection')});
